"""Platform preconditions, run once at startup.
A block that mints its own id needs that id created BEFORE any
capability calls it. Generated from the factory's resource
obligations (R1c) rather than left to each handler to remember.

This is the CLAIMS platform's obligation list. The one block this roster
binds whose contract both mints an id and consumes it is ``task_listing``:
adjuster_routing_approval puts every claim on the insurer's routing board,
and task_listing's own ``create`` operation is what mints that board's
listing id -- validate/distance_match/filter_search/suggest_price_band all
read it. Minting a board per request would put a fresh, empty board in
front of every adjuster, so the platform mints ONE board here and every
call carries the id this module recorded.

The winery build's ``team`` obligation is gone with the ``team`` block: no
block this insurer binds creates an organisation, a tenant or a crew.
Claim references are not minted by a block either -- claim_registration
assigns them from the claimant record at intake -- so they are not an
obligation here.

``resource_id(block_id)`` returns the id the ensure step received, or
None when the step has not run or did not succeed.
"""

from __future__ import annotations

import logging
from typing import Any, Dict, Optional

_LOG = logging.getLogger(__name__)

#: block_id -> the id its ensure action returned.
RESOURCE_IDS: Dict[str, str] = {}
#: block_id -> why its ensure step did not produce an id.
RESOURCE_ERRORS: Dict[str, str] = {}

PRECONDITIONS: Dict[str, Dict[str, Any]] = {
    "task_listing": {
        "ensure": "create",
        "carry": "listing_id",
        "input": {
            "title": "Claims routing board",
            "description": "The insurer's standing board of claims awaiting "
                           "adjuster routing.",
            "category": "admin",
            "location": {"address": "United Kingdom"},
        },
        "into": [
            "validate",
            "distance_match",
            "filter_search",
            "suggest_price_band",
        ],
    },
}


def resource_id(block_id: str) -> Optional[str]:
    """The id ``ensure_all`` obtained for this block, if any."""
    return RESOURCE_IDS.get(block_id)


def ensure_all() -> Dict[str, Any]:
    """Run every platform precondition. Idempotent; never raises."""
    try:
        from app.dispatch import execute
    except Exception as exc:  # noqa: BLE001 - boot must not die
        for block_id in PRECONDITIONS:
            RESOURCE_ERRORS[block_id] = "%s: %s" % (type(exc).__name__, exc)
        _LOG.warning(
            "preconditions could not reach the block dispatcher: %s", exc,
        )
        return {"ids": dict(RESOURCE_IDS), "errors": dict(RESOURCE_ERRORS)}

    for block_id, rule in PRECONDITIONS.items():
        if RESOURCE_IDS.get(block_id):
            continue
        ensure = rule.get("ensure")
        carry = rule.get("carry")
        if not ensure or not carry:
            RESOURCE_ERRORS[block_id] = (
                "precondition names no ensure action and id to carry"
            )
            _LOG.warning(
                "precondition %s is not a rule this module can run", block_id,
            )
            continue
        try:
            result = execute(
                block_id, dict(rule.get("input") or {}), action=ensure
            )
        except Exception as exc:  # noqa: BLE001 - boot must not die
            RESOURCE_ERRORS[block_id] = "%s: %s" % (
                type(exc).__name__, exc,
            )
            _LOG.warning(
                "precondition %s %s raised: %s",
                block_id, ensure, exc,
            )
            continue
        got = None
        if isinstance(result, dict):
            got = result.get(carry)
            if got is None and isinstance(result.get("result"), dict):
                got = result["result"].get(carry)
        if got:
            RESOURCE_IDS[block_id] = str(got)
            RESOURCE_ERRORS.pop(block_id, None)
        else:
            RESOURCE_ERRORS[block_id] = str(
                (result or {}).get("error") if isinstance(result, dict)
                else result
            )[:200]
            _LOG.warning(
                "precondition %s %s returned no %s: %s",
                block_id, ensure, carry,
                RESOURCE_ERRORS[block_id],
            )
    return {"ids": dict(RESOURCE_IDS), "errors": dict(RESOURCE_ERRORS)}

