def _settings_aliases(tree: ast.AST) -> Set[str]:
    """Local names bound to the money settings module or its accessors."""
    aliases: Set[str] = set()
    package, _, leaf = MONEY_SETTINGS_MODULE.rpartition(".")
    for node in ast.walk(tree):
